const STORIES_DATA = [{"id": "atoj-alqo-parte-1", "section": 1, "part": 1, "title": "Atojwan Alqowan — Parte 1", "subtitle": "El zorro en la chacra", "icon": "🦊", "level": "Básico", "xp": 15, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Uj p'unchay...", "e": "Un día..."}, {"type": "text", "speaker": "narrator", "q": "Atojqa chajrapi kashan.", "e": "El zorro está en la chacra."}, {"type": "text", "speaker": "narrator", "q": "Payqa kusisqa kashan.", "e": "Él está feliz."}, {"type": "question", "title": "¿Pitaj chajrapi kashan?", "text": "¿Quién está en la chacra?", "options": ["Atoj (el zorro)", "Alqo (el perro)"], "correct": 0, "explanation": ""}, {"type": "text", "speaker": "narrator", "q": "Chajraqa sumaj. Inti kashan.", "e": "La chacra es hermosa. Hay sol."}, {"type": "text", "speaker": "narrator", "q": "Mana parachu. Mana phuyuchu.", "e": "No hay lluvia. No hay nubes."}, {"type": "question", "title": "¿Imaynatataj p'unchay kashan?", "text": "¿Cómo está el día?", "options": ["Paramushan (Está lloviendo)", "Inti kashan (Hay sol)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — ¡Sumaj p'unchay!", "e": "El zorro dice: — ¡Qué lindo día!"}, {"type": "text", "speaker": "narrator", "q": "Payqa sapa p'unchay chajraman rin.", "e": "Él va a la chacra todos los días."}, {"type": "question", "title": "¿Imayná atoj kashan?", "text": "¿Cómo está el zorro?", "options": ["Llakisqa (Triste)", "Kusisqa (Feliz)"], "correct": 1, "explanation": ""}]}, {"id": "atoj-alqo-parte-2", "section": 1, "part": 2, "title": "Atojwan Alqowan — Parte 2", "subtitle": "Un encuentro en el camino", "icon": "🌧️", "level": "Básico", "xp": 15, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Ñanpi, uj alqo kashan.", "e": "En el camino, hay un perro."}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — ¡Imaynalla!", "e": "El perro dice: — ¡Hola!"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Imaynalla! ¿Ima sutiyki?", "e": "El zorro dice: — ¡Hola! ¿Cómo te llamás?"}, {"type": "question", "title": "¿Pitaj ñanpi kashan?", "text": "¿Quién está en el camino?", "options": ["Atoj (el zorro)", "Alqo (el perro)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Sutiy Runtu. ¿Qanrí?", "e": "El perro dice: — Mi nombre es Runtu. ¿Y vos?"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Noqa Puma sutikuni. Kusikuni rejsisuspa.", "e": "El zorro dice: — Yo me llamo Puma. Encantado de conocerte."}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Noqapis. ¿Maymanta kanki?", "e": "El perro dice: — Yo también. ¿De dónde sos?"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Orqo llajtamanta kani. ¿Qanrí?", "e": "El zorro dice: — Soy del pueblo del cerro. ¿Y vos?"}, {"type": "question", "title": "¿Maymantataj atoj?", "text": "¿De dónde es el zorro?", "options": ["Orqo llajtamanta (Del pueblo del cerro)", "Mayu llajtamanta (Del pueblo del río)"], "correct": 0, "explanation": ""}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Noqa mayu llajtamanta kani. ¡Kusikuni rejsisuspa!", "e": "El perro dice: — Yo soy del pueblo del río. ¡Estoy feliz de conocerte!"}]}, {"id": "atoj-alqo-parte-3", "section": 1, "part": 3, "title": "Atojwan Alqowan — Parte 3", "subtitle": "La chacra de los dos", "icon": "🐕", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "atojqa", "q": "Atojqa: — ¿Mayman rishanki, Runtu?", "e": "El zorro dice: — ¿Adónde estás yendo, Runtu?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Chajraman rishani. ¿Qanrí?", "e": "El perro dice: — Estoy yendo a la chacra. ¿Y vos?"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Noqapis chajraman rishani. ¿Wasichu chajrachu astawan gustasunki?", "e": "El zorro dice: — Yo también voy a la chacra. ¿Te gusta más la casa o la chacra?"}, {"type": "question", "title": "¿Mayman rinku iskayninku?", "text": "¿Adónde van los dos?", "options": ["Chajraman (A la chacra)", "Wasiyman (A la casa)"], "correct": 0, "explanation": ""}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Chajra mayta gustawan! Chajraqa sumaj.", "e": "El perro dice: — ¡Me encanta la chacra! La chacra es hermosa."}, {"type": "text", "speaker": "narrator", "q": "Chajrapi ashkha runas tiyan. Wakinninku yachachejkuna kanku.", "e": "En la chacra hay muchas personas. Algunos de ellos son maestros."}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — ¿Pitaj paykuna kanku?", "e": "El zorro dice: — ¿Quiénes son ellos?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Paykunaqa yachachejkuna kanku. Paykunaqa mana atojkunachu kanku.", "e": "El perro dice: — Ellos son maestros. Ellos no son zorros."}, {"type": "question", "title": "¿Pitaj paykuna kanku?", "text": "¿Quiénes son ellos?", "options": ["Atojkuna (Zorros)", "Yachachejkuna (Maestros)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "narrator", "q": "Atojqa mana phiñasqachu. Payqa kusisqa kashan yachachejkunawan.", "e": "El zorro no está enojado. Él está feliz con los maestros."}]}, {"id": "atoj-alqo-parte-4", "section": 1, "part": 4, "title": "Atojwan Alqowan — Parte 4", "subtitle": "El viaje juntos", "icon": "🛤️", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Chaymantataj, atojqa tapun: — ¿Imapí llajtaman rinki?", "e": "Después, el zorro pregunta: — ¿En qué vas a la ciudad?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Chakipi rini. Mana autoyojchu kani. ¿Qanrí?", "e": "El perro dice: — Voy a pie. No tengo auto. ¿Y vos?"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Noqapis chakipi rini. ¿Autopichu colectivopichu astawan gustasunki?", "e": "El zorro dice: — Yo también voy a pie. ¿Te gusta más en auto o en colectivo?"}, {"type": "question", "title": "¿Imapí rinku llajtaman?", "text": "¿En qué van los dos a la ciudad?", "options": ["Chakipi (A pie)", "Autopi (En auto)"], "correct": 0, "explanation": ""}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Colectivopi gustawan! Jinapis mana colectivoyoj kanchej.", "e": "El perro dice: — ¡Me gusta el colectivo! Pero no tenemos colectivo."}, {"type": "text", "speaker": "narrator", "q": "Ñanpi parlanku. Atojqa tapun: — ¿Maymantataj jamushanki kunan?", "e": "En el camino conversan. El zorro pregunta: — ¿De dónde venís ahora?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — Mayu llajtamanta jamushani. Sapa p'unchay chajraman rini.", "e": "El perro dice: — Vengo del pueblo del río. Todos los días voy a la chacra."}, {"type": "question", "title": "¿Maymanta jamun alqo?", "text": "¿De dónde viene el perro?", "options": ["Orqo llajtamanta (Del pueblo del cerro)", "Mayu llajtamanta (Del pueblo del río)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — Noqapis sapa p'unchay chajraman rini. ¡Noqanchej llank'ajkuna kanchej!", "e": "El zorro dice: — ¡Yo también voy a la chacra todos los días. ¡Nosotros somos trabajadores!"}, {"type": "text", "speaker": "narrator", "q": "Iskayninku kusisqa kanku. Chajraman khuskha rinku.", "e": "Los dos están felices. Van juntos a la chacra."}]}, {"id": "atoj-alqo-parte-5", "section": 1, "part": 5, "title": "Atojwan Alqowan — Parte 5", "subtitle": "Amigos para siempre", "icon": "🌟", "level": "Intermedio", "xp": 20, "badge_id": "atoj-alqo-parte-5-badge", "scenes": [{"type": "text", "speaker": "narrator", "q": "Chajraman chayankuña. Atojqa tapun: — ¿Qhechuata yachakuyta munankichu?", "e": "Ya llegan a la chacra. El zorro pregunta: — ¿Querés aprender quechua?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — ¡Ari! Quechuata yachakuyta munani. ¿Qanrí?", "e": "El perro dice: — ¡Sí! Quiero aprender quechua. ¿Y vos?"}, {"type": "text", "speaker": "atojqa", "q": "Atojqa: — ¡Noqapis! Sapa p'unchay yachakusaj.", "e": "El zorro dice: — ¡Yo también! Aprenderé todos los días."}, {"type": "question", "title": "¿Imatá munanku iskayninku?", "text": "¿Qué quieren los dos?", "options": ["Llajtaman riy (Ir a la ciudad)", "Quechuata yachakuy (Aprender quechua)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "narrator", "q": "Chaymantataj, atojqa nin: — ¿Piwan jamunki cursoman?", "e": "Después, el zorro dice: — ¿Con quién vas al curso?"}, {"type": "text", "speaker": "alqoqa", "q": "Alqoqa: — ¡Qanwan risaj! Qanqa amigoy kanki.", "e": "El perro dice: — ¡Iré con vos! Vos sos mi amigo."}, {"type": "text", "speaker": "narrator", "q": "Atojqa kusisqa kashan. Mana llakisqachu, mana sayk'usqachu.", "e": "El zorro está feliz. No está triste, no está cansado."}, {"type": "question", "title": "¿Imayná kashan atoj tukukuypi?", "text": "¿Cómo está el zorro al final?", "options": ["Sayk'usqa (Cansado)", "Kusisqa (Feliz)", "Llakisqa (Triste)"], "correct": 1, "explanation": ""}, {"type": "text", "speaker": "narrator", "q": "Atojwan alqowan — amigos kanku. Sapa p'unchay parlanku, sapa p'unchay yachakunku.", "e": "El zorro y el perro — son amigos. Todos los días conversan, todos los días aprenden."}, {"type": "text", "speaker": "narrator", "q": "Tukukuy. ¡Sumaj cuento!", "e": "Fin. ¡Qué lindo cuento!"}]}, {"id": "carmen-maria-parte-1", "section": 3, "part": 1, "title": "Carmen y María — Parte 1", "subtitle": "En el colectivo", "icon": "🚌", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Uj paqarin, Carmen colectivopi tiyaykun.", "e": "Una mañana, Carmen se sienta en el colectivo."}, {"type": "text", "speaker": "narrator", "q": "Paypa qayllanpi uj warmi tiyashan. Payqa María.", "e": "Cerca de ella hay una señora sentada. Ella es María."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Imaynalla! ¿Walejllachu?", "e": "Carmen: — ¡Hola! ¿Bien nomás?"}, {"type": "text", "speaker": "maría", "q": "María: — Arí, walejlla. ¿Qanrí?", "e": "María: — Sí, bien nomás. ¿Y vos?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Walejllapis. Noqa Carmen sutikuni. ¿Qanrí, ima sutiyki?", "e": "Carmen: — Bien también. Yo me llamo Carmen. ¿Y vos, cómo te llamás?"}, {"type": "text", "speaker": "maría", "q": "María: — Noqa María sutikuni. Kusikuni rejsisuspa.", "e": "María: — Yo me llamo María. Encantada de conocerte."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Noqapis. ¿Maymantá kanki?", "e": "Carmen: — Yo también. ¿De dónde sos?"}, {"type": "text", "speaker": "maría", "q": "María: — Kay llajtamanta kani. Wasiy karullapi kashan.", "e": "María: — Soy de este pueblo. Mi casa está un poco lejos."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¿Quechuata parlankichu?", "e": "Carmen: — ¿Hablás quechua?"}, {"type": "text", "speaker": "maría", "q": "María: — Ari, tumpata. Mamayta uyarispa yachakuni.", "e": "María: — Sí, un poco. Aprendo escuchando a mi mamá."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Sumaj! Noqapis quechuata yachakushani, runaswan Bibliamanta parlarinaypaj.", "e": "Carmen: — ¡Qué hermoso! Yo también estoy aprendiendo quechua, para hablar con las personas de la Biblia."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Ah, cheqamanta! Sumaj.", "e": "María: — ¡Ah, de verdad! Qué bueno."}, {"type": "question", "title": "¿Imarayku Carmen quechuata yachakushan?", "text": "¿Por qué está aprendiendo quechua Carmen?", "options": ["Runaswan Bibliamanta parlarinanpaj (Para hablar con las personas de la Biblia)", "Cursopi yachakuyta munasqanrayku (Porque quiere aprender en el curso)", "Colectivopi parlarinanpaj (Para hablar en el colectivo)"], "correct": 0, "explanation": ""}]}, {"id": "carmen-maria-parte-2", "section": 3, "part": 2, "title": "Carmen y María — Parte 2", "subtitle": "Quedan en encontrarse", "icon": "🤝", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Carmen Mariata tapun: — ¿Imaynataj familiaykiri?", "e": "Carmen le pregunta a María: — ¿Cómo está tu familia?"}, {"type": "text", "speaker": "maría", "q": "María: — Allillan kashanku. Wawasniy kusisqa kashanku.", "e": "María: — Están bien nomás. Mis hijos están felices."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — María, uj tapuyta ruwarisqayki. ¿Imataj kunan tiempopi astawan llakichishasunki?", "e": "Carmen: — María, te haré una pregunta. ¿Qué le hace angustiar más en este tiempo?"}, {"type": "text", "speaker": "maría", "q": "María: — emm, sapa p'unchay familiaymanta llakikuni.", "e": "María: — emm, todos los días me preocupo por mi familia."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Entiendeyki doña. Noqamanpis ajina pasawan. Pero Biblia mayta yanapawan. ¿Imayrakuchus yachayta munawajchu?", "e": "Carmen: — Le entiendo doña. A mí también me pasa. Pero la Biblia me ayuda mucho. ¿Quisiera saber por qué?"}, {"type": "text", "speaker": "maría", "q": "María: — Arí, munayman.", "e": "María: — Sí, con gusto."}, {"type": "question", "title": "¿María Bibliamanta yachayta munanman?", "text": "¿María quisiera saber de la Biblia?", "options": ["Ichá", "Arí", "Mana"], "correct": 1, "explanation": ""}]}, {"id": "carmen-maria-parte-3", "section": 3, "part": 3, "title": "Carmen y María — Parte 3", "subtitle": "El video por celular", "icon": "📱", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Viernes p'unchay manaraj chayamunchu. Carmen celularnejta Maríata uj mensajeta qhelqan.", "e": "Todavía no llegó el viernes. Carmen escribe mediante su celular un mensaje a María."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Imaynalla María. Uj sumaj videitota apachimuyki. Rikuriy.", "e": "Carmen: — Hola María. Te envío un videito hermoso. Miralo."}, {"type": "text", "speaker": "narrator", "q": "María videitota qhawan. Payqa mayta kusikun.", "e": "María mira el videito. Ella se alegra mucho."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Sumaj videito! ¿Sut'inchawankimanchu?", "e": "María: — ¡Qué lindo videito! ¿Me lo puedes aclarar?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Familiamanta parlashan. Dios familiasta yanapayta munan.", "e": "Carmen: — Está hablando de la familia. Dios quiere ayudar a las familias."}, {"type": "text", "speaker": "maría", "q": "María: — ¿Cheqamantachu?", "e": "María: — ¿De verdad?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí. Chaymanta viernes astawan parlarisunchej.", "e": "Carmen: — Sí. De eso el viernes conversaremos más."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Sumaj! Suyasqayki.", "e": "María: — ¡Qué bueno! Te esperaré."}, {"type": "question", "title": "¿Imatataj parlashan videito?", "text": "¿De qué está hablando el videito?", "options": ["Familiamanta", "Colectivomanta", "Quechuamanta"], "correct": 0, "explanation": ""}]}, {"id": "carmen-maria-parte-4", "section": 3, "part": 4, "title": "Carmen y María — Parte 4", "subtitle": "En la casa de María", "icon": "🏠", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Viernes p'unchay chayamun. Carmen Maríaj wasinman chayan.", "e": "Llega el viernes. Carmen llega a la casa de María."}, {"type": "text", "speaker": "narrator", "q": "María punkuta kichan: — ¡Imaynalla Carmen! ¡Pasaykamuy!", "e": "María abre la puerta: — ¡Hola Carmen! ¡Pasá!"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Imaynalla María! Sumaj wasiyki.", "e": "Carmen: — ¡Hola María! Qué linda tu casa."}, {"type": "text", "speaker": "narrator", "q": "Wawasnin paykunata qhawanku, manchachikuspa pakakunku.", "e": "Sus hijos las miran, asustados se esconden."}, {"type": "text", "speaker": "narrator", "q": "Carmen asikun: — ¡Sumaj wawas! ¿Ima sutiykichej?", "e": "Carmen se ríe: — ¡Qué lindos tus hijos! ¿Cómo se llaman?"}, {"type": "text", "speaker": "maría", "q": "María: — Kayqa Lucía, kayqa Tomás, kayqa Sofía.", "e": "María: — Esta es Lucía, este es Tomás, esta es la bebé Sofía."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Tukuy sumaj! Familiayki kusisqa kananpaj, ¿imatá yanapanman?", "e": "Carmen: — ¡Todos son hermosos! Para que tu familia sea feliz, ¿qué podría ayudar?"}, {"type": "text", "speaker": "maría", "q": "María: — Mana yachanichu. Paykunarayku anchata llank'ani.", "e": "María: — No sé. Trabajo mucho por ellos."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Bibliamanta yachakoyqa yanapawanchej. Diosqa munan familianchejwan kusisqa kausakunanchejta.", "e": "Carmen: — Aprender de la Biblia nos ayuda. Dios quiere que vivamos felices con nuestra familia."}, {"type": "text", "speaker": "maría", "q": "María: — ¿Cheqamantachu? Noqa Bibliapi creeni, jinapis mana leeyta yachanichu.", "e": "María: — ¿De verdad? Yo creo en la Biblia, pero no la suelo leer."}, {"type": "question", "title": "¿Imatá nin Carmen familianwan kusisqa kananpaj?", "text": "¿Qué dice Carmen para ser feliz con su familia?", "options": ["Ashkha qolqeyoj", "Bibliamanta yachakuy", "Anchata llank'ay"], "correct": 1, "explanation": ""}]}, {"id": "carmen-maria-parte-5", "section": 3, "part": 5, "title": "Carmen y María — Parte 5", "subtitle": "La revista y la despedida", "icon": "📖", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Carmen carteranmanta uj revistata orqhon.", "e": "Carmen saca de su cartera una revista."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Kay revistapi familiamanta parlakushan. Leerinaykipaj saqerisqayki, ¿ya?", "e": "Carmen: — En esta revista se está hablando de la familia. Te la dejo para que leas, ¿ya?"}, {"type": "text", "speaker": "maría", "q": "María: — ¡Pachis! Leerisaj.", "e": "María: — ¡Gracias! La voy a leer."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Uj textitota leeripuyta munani. ¿Uyariwajchu?", "e": "Carmen: — Quisiera leerle un textito. ¿Me escucharía?"}, {"type": "text", "speaker": "maría", "q": "María: — Arí, uyarini.", "e": "María: — Sí, te escucho."}, {"type": "text", "speaker": "narrator", "q": "Carmen Bibliata orqhospa nin: — Leerina kay Salmos nisqanta.", "e": "Carmen sacando su Biblia dice: — Leamos lo que dice Salmos."}, {"type": "text", "speaker": "narrator", "q": "Carmen leeripun. María uyarin. Sonqonman chayan.", "e": "Carmen se lo lee. María escucha. Le llega a su corazón."}, {"type": "text", "speaker": "maría", "q": "María: — May sumaj texto.", "e": "María: — Qué hermoso texto."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí, Biblia mayta yanapawanchej. Waj p'unchay kutimuspa, chaymanta parlarisunman.", "e": "Carmen: — Sí, la Biblia nos ayuda mucho. Cuando vuelva otro día, podemos hablar de eso."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Sumaj! Suyasqayki.", "e": "María: — ¡Qué bueno! La espero."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Waj kutikama, María.", "e": "Carmen: — Hasta otro momento, María."}, {"type": "question", "title": "¿Imatataj Carmen saqen Mariaman?", "text": "¿Qué le deja Carmen a María?", "options": ["Uj revistata", "Uj tarjetitata", "Uj videitota"], "correct": 0, "explanation": ""}]}, {"id": "carmen-maria-parte-6", "section": 3, "part": 6, "title": "Carmen y María — Parte 6", "subtitle": "El segundo encuentro", "icon": "☀️", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Waj p'unchay Carmen kutimun. Allin paqarin.", "e": "Otro día vuelve Carmen. Linda mañana."}, {"type": "text", "speaker": "narrator", "q": "María punkuta kichan: — ¡Carmen! ¡Suyashani!", "e": "María abre la puerta: — ¡Carmen! ¡Te estaba esperando!"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Imaynalla, María. ¿Imaynalla kakushanki?", "e": "Carmen: — Hola, María. ¿Cómo te estás encontrando?"}, {"type": "text", "speaker": "maría", "q": "María: — Walejlla kashani. Kunan paqarin inti llipirishan.", "e": "María: — Estoy bien nomás. Esta mañana brilla el sol."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí, sumaj p'unchay.", "e": "Carmen: — Sí, lindo día."}, {"type": "text", "speaker": "maría", "q": "María: — Revistata leerqaniña", "e": "María: — Ya leí la revista"}, {"type": "text", "speaker": "narrator", "q": "Carmen asikun: — ¡May sumaj leerisqaykimanta!", "e": "Carmen se ríe: — ¡Qué bueno que la pudiste leer!"}, {"type": "text", "speaker": "maría", "q": "María: — Arí, leerqaniña. Kay revistapi familiamanta ashkhata parlakushan.", "e": "María: — Sí, ya la leí. En esta revista se está hablando mucho de la familia."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¿Mayqen partetaj astawan gustasunki?", "e": "Carmen: — ¿Cuál parte te gustó más?"}, {"type": "text", "speaker": "maría", "q": "María: — Diosqa Familiawan kusisqa kausakunanchejta munan.", "e": "María: — Dios quiere que vivamos felices con la familia."}, {"type": "question", "title": "María ¿revistata leerqaña?", "text": "¿Ya leyó la revista María?", "options": ["Arí", "Ichá", "Mana"], "correct": 0, "explanation": ""}]}, {"id": "carmen-maria-parte-7", "section": 3, "part": 7, "title": "Carmen y María — Parte 7", "subtitle": "Hablando de la familia", "icon": "👨‍👩‍👧‍👦", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "carmen", "q": "Carmen: — María, ¿Familiaykiwan kusisqa kausakunaykipaj, imatá ruwawaj?", "e": "Carmen: — María, ¿qué podrías hacer para vivir feliz con tu familia?"}, {"type": "text", "speaker": "maría", "q": "María: — Mana yachanichu. Wakenqa ninku qolqewan kusisqa kasqankuta.", "e": "María: — No sé. Algunos dicen que son felices con el dinero."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Ashkhas runas ajinallata yuyanku. Jinapis Biblia yachachin waj imatapis.", "e": "Carmen: — Muchas personas piensan así nomás. Pero la Biblia enseña otra cosa."}, {"type": "text", "speaker": "maría", "q": "María: — ¿Imatá Biblia yachachin?", "e": "María: — ¿Qué enseña la Biblia?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Sapa día Diospa palabranta uyarispaqa familiawan kusisqa kasunchej.", "e": "Carmen: — Escuchando todos los días la palabra de Dios seremos felices con la familia."}, {"type": "text", "speaker": "narrator", "q": "Carmen Biblianta kichan: — Uj Bibliamanta textota leeriyta munani. ¿Atiwajchu?", "e": "Carmen abre su Biblia: — Quisiera leerte un texto de la Biblia. ¿Podés?"}, {"type": "text", "speaker": "maría", "q": "María: — Arí, uyarini.", "e": "María: — Sí, te escucho."}, {"type": "text", "speaker": "narrator", "q": "Carmen leeripun. Chaymanta tapun: — Kaypi, ¿imatá Diosmanta nishawanchej?", "e": "Carmen se lo lee. Luego pregunta: — Aquí, ¿qué nos está diciendo de Dios?"}, {"type": "text", "speaker": "maría", "q": "María: — Dios anchata munakuwanchej... ¿icharí?", "e": "María: — Que Dios nos quiere mucho a nosotros. ¿Verdad?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Cheqapuni! Leesqanchejman jina, Dios tukuyninchejta munakuwanchej, yanapawanchejtaj.", "e": "Carmen: — ¡Exactamente! Como leímos, Dios nos quiere a todos y nos ayuda."}, {"type": "question", "title": "¿Imatataj Biblia yachachin Diosmanta?", "text": "¿Qué enseña la Biblia sobre Dios?", "options": ["Pay mana munakuwanchejchu", "Pay pisillata munakuwanchej", "Pay anchata munakuwanchej"], "correct": 2, "explanation": ""}]}, {"id": "carmen-maria-parte-8", "section": 3, "part": 8, "title": "Carmen y María — Parte 8", "subtitle": "Otro video: el futuro", "icon": "🌟", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Waj p'unchay Carmen celularninpi Maríata qhelqan.", "e": "Otro día, Carmen escribe en su celular a María."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Imaynalla María. Rikuriy kay videitota. Ajinata sutikun: 'Allin kausay qhepaman'.", "e": "Carmen: — Hola María. Mirá este videito. Se llama así: 'Paz en el futuro'."}, {"type": "text", "speaker": "narrator", "q": "María videitota qhawan. Sonqonman chayan.", "e": "María mira el videito. Llega a su corazón."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Sumaj videito! ¿Maykʼajllapis ajina kanqachu?", "e": "María: — ¡Qué lindo videito! ¿Alguna vez será así?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí. Biblia chayta prometewanchej. Niña sajra runas kajtin, niña makanakuykuna, ni guerraspis kanqachu.", "e": "Carmen: — Sí. La Biblia nos promete eso. Cuando ya no haya personas malas, ya no habrá peleas ni guerras."}, {"type": "text", "speaker": "maría", "q": "María: — ¿Cheqamantachu? ¿Mayk'aj kanqa chay?", "e": "María: — ¿De verdad? ¿Cuándo será eso?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Waj p'unchay kutimuspa chay tapuyman kutichisusqayki. Chaymanta qhepanpi parlarisunman.", "e": "Carmen: — Cuando vuelva otro día te responderé esa pregunta. En la próxima podemos hablar de eso."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Sumaj!", "e": "María: — ¡Qué bueno!"}, {"type": "question", "title": "¿Imatataj prometewanchej Biblia?", "text": "¿Qué nos promete la Biblia?", "options": ["Niña sajra runas kajtin, ni makanakuykuna, ni guerraspis kanqachu", "Sapa p'unchay paramonqa", "Ni jayk'aj allin kausayta atikonqachu"], "correct": 0, "explanation": ""}]}, {"id": "carmen-maria-parte-9", "section": 3, "part": 9, "title": "Carmen y María — Parte 9", "subtitle": "¿Qué pasará en el futuro?", "icon": "🌈", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Carmen kutimun. María kusisqa punkuta kichan.", "e": "Carmen vuelve. María abre la puerta contenta."}, {"type": "text", "speaker": "maría", "q": "María: — ¡Kusikuni watejmanta rikususpa Carmen!", "e": "María: — ¡Me alegro de verte de nuevo!"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Kusikuni kaypi kutimusqaymanta. Qaninpa uj tapuyta saqenchej kutichinanchejpaj", "e": "Carmen: — Me alegra haber vuelto. La otra vez dejamos una pregunta para responder"}, {"type": "text", "speaker": "maría", "q": "María: — Arí! ¿Mayk'aj kanqa chay allin kausay?", "e": "María: — ¡Sí! ¿Cuándo será esa buena vida?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¿Yacharqankichu tumpamantawan tukuypis sanitos kananchejta?", "e": "Carmen: — ¿Sabía que muy pronto todos estaremos bien de salud?"}, {"type": "text", "speaker": "maría", "q": "María: — ¡Mana! ¿Cheqamantachu? ¿Wañusqaspis kausarimuytachu atinkuman?", "e": "María: — ¡No! ¿De verdad? ¿Los muertos también podrían resucitar?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí, Biblia chayta niwanchej. Chaypajqa Bibliamanta leerisunman.", "e": "Carmen: — Sí, la Biblia nos dice eso. Para eso podemos leerlo de la Biblia."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¿Munawajchu wiñaypaj kusisqa kausakuyta familiaykiwan?", "e": "Carmen: — ¿Quisiera vivir para siempre feliz con su familia?"}, {"type": "text", "speaker": "maría", "q": "María: — ¡Arí! Chayta sapa tutay mañakuni.", "e": "María: — ¡Sí! Eso es lo que pido cada noche."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Orakusqanchejta Dios uyariwanchej. Pay yanapawanchej.", "e": "Carmen: — Lo que oramos, Dios nos escucha. Él nos ayuda."}, {"type": "question", "title": "¿Imatataj Carmen tapun Mariaman?", "text": "¿Qué le pregunta Carmen a María?", "options": ["¿Colectivopi riwajchu?", "¿Quechuata parlankichu?", "¿Munawajchu wiñaypaj kusisqa kausakuyta?"], "correct": 2, "explanation": ""}]}, {"id": "carmen-maria-parte-10", "section": 3, "part": 10, "title": "Carmen y María — Parte 10", "subtitle": "Un nuevo comienzo", "icon": "⭐", "level": "Intermedio", "xp": 20, "badge_id": "carmen-maria-parte-10-badge", "scenes": [{"type": "text", "speaker": "narrator", "q": "Carmen Biblianmanta leeripun.", "e": "Carmen lee de la Biblia."}, {"type": "text", "speaker": "maría", "q": "María: — ¿Maykʼajllapis sajra imasta chinkanqachu?", "e": "María: — ¿Desaparecerán alguna vez las cosas malas?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Arí. ¿Pitaj chay imasta chinkachenqa?", "e": "Carmen: — Sí. ¿Y quién hará desaparecer esas cosas?"}, {"type": "text", "speaker": "narrator", "q": "María yuyarin: — ¿Dioschu?", "e": "María piensa: — ¿Dios?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Ajinapuni! Leerinchej jina, Diospa Gobiernonqa sajra imasta chinkachenqa.", "e": "Carmen: — ¡Exactamente! Como leímos, el Gobierno de Dios hará desaparecer esas cosas."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Niña makanakuykuna, ni guerraspis kanqachu. Tukuypis sanitos kananchejta Biblia prometewanchej.", "e": "Carmen: — Ya no habrá peleas ni guerras. La Biblia promete que todos estaremos sanos."}, {"type": "text", "speaker": "narrator", "q": "María t'ukurin. — Noqa chay kausayta munani. Bibliamanta astawan yachakuyta munani.", "e": "María medita. — Yo quiero esa vida. Quiero aprender más de la Biblia."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — ¡Sumaj! Internetman yaykuspa, ashkha yachachiykunata, videosta ima tukuypaj tarinki.", "e": "Carmen: — ¡Muy bien! Entrando en Internet, vas a encontrar muchas enseñanzas y videos para todos."}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Kay tarjetitata saqerisqayki. Chaypi tukuy chayta tarinki.", "e": "Carmen: — Te dejo esta tarjetita. Ahí encontrarás todo."}, {"type": "text", "speaker": "narrator", "q": "María tarjetitata japʼin. Payqa kusisqa kashan. ¡Uj mosoj qallariy!", "e": "María recibe la tarjetita. Ella está feliz. ¡Un nuevo comienzo!"}, {"type": "question", "title": "¿Imatataj munan María tukukuypi?", "text": "¿Qué quiere María al final?", "options": ["Bibliamanta astawan yachakuyta", "Colectivopi riyta", "Quechuata manaña parlariyta"], "correct": 0, "explanation": ""}]}, {"id": "inti-parte-1", "section": 1, "part": 1, "title": "Inti, tapurikoj wayna — Parte 1", "subtitle": "La partida", "icon": "🌅", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Uj p'unchay, Inti wasiymanta ripun.", "e": "Un día, Inti se va de su casa."}, {"type": "text", "speaker": "narrator", "q": "Payqa kusisqa. Llajtaman rishanki.", "e": "Él está feliz. Está yendo a la ciudad."}, {"type": "text", "speaker": "narrator", "q": "Chakipi rin. Orqos, mayus, phuyus... ¡sumaj!", "e": "Va a pie. Cerros, ríos, nubes... ¡qué lindo!"}, {"type": "text", "speaker": "narrator", "q": "Ñanpi, doña Rosa kashan.", "e": "En el camino está doña Rosa."}, {"type": "text", "speaker": "inti", "q": "Inti: — Imaynalla, doña!", "e": "Inti: — ¡Hola, señora!"}, {"type": "text", "speaker": "narrator", "q": "Intej wasin orqo patapi kashan.", "e": "La casa de Inti está arriba del cerro."}, {"type": "text", "speaker": "narrator", "q": "Payqa wayna. Uj tapurikoj wayna.", "e": "Él es un joven. Un joven que hace preguntas."}, {"type": "question", "title": "¿Mayman rin Inti?", "text": "¿Adónde va Inti?", "options": ["Mercadoman (Al mercado)", "Llajtaman (A la ciudad)", "Wasiyman (A su casa)"], "correct": 1, "explanation": ""}]}, {"id": "inti-parte-2", "section": 1, "part": 2, "title": "Inti, tapurikoj wayna — Parte 2", "subtitle": "Doña Rosa", "icon": "👵", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "rosa", "q": "Rosa: — Allin p'unchay, wayna! ¿Imaynalla kashanki?", "e": "Rosa: — ¡Buenos días, joven! ¿Cómo estás?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Walejlla kashani. ¿Qanrí, doña?", "e": "Inti: — Estoy bien nomás. ¿Y usted, señora?"}, {"type": "text", "speaker": "rosa", "q": "Rosa: — Noqapis walejlla, gracias. ¿Ima sutiyki?", "e": "Rosa: — Yo también bien, gracias. ¿Cuál es tu nombre?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Sutiy Inti. Kusikuni rejsisuspa, doña Rosa.", "e": "Inti: — Mi nombre es Inti. Encantado de conocerla, doña Rosa."}, {"type": "text", "speaker": "rosa", "q": "Rosa: — Noqapis. ¿Maymanta kanki?", "e": "Rosa: — Yo también. ¿De dónde sos?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Orqo llajtamanta kani. ¿Qanrí?", "e": "Inti: — Soy del pueblo del cerro. ¿Y usted?"}, {"type": "text", "speaker": "rosa", "q": "Rosa: — Noqaqa mayu llajtamanta kani. ¿Mayman rishanki?", "e": "Rosa: — Yo soy del pueblo del río. ¿Adónde estás yendo?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Llajtaman rishani. Waj runasta rejsiyta munani.", "e": "Inti: — Estoy yendo a la ciudad. Quiero conocer a otras personas."}, {"type": "text", "speaker": "rosa", "q": "Rosa: — ¡Sumaj! Tinkunakama, wayna.", "e": "Rosa: — ¡Qué bueno! Nos vemos, joven."}, {"type": "question", "title": "¿Maymanta kashan Inti?", "text": "¿De dónde es Inti?", "options": ["Kay llajtamanta (De este pueblo)", "Orqo llajtamanta (Del pueblo del cerro)", "Mayu llajtamanta (Del pueblo del río)"], "correct": 1, "explanation": ""}]}, {"id": "inti-parte-3", "section": 1, "part": 3, "title": "Inti, tapurikoj wayna — Parte 3", "subtitle": "Don Marcos", "icon": "👨", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Inti llajtaman chayan. Jatun llajta, icharí.", "e": "Inti llega a la ciudad. Es un pueblo grande, ¿verdad?"}, {"type": "text", "speaker": "narrator", "q": "Chaypi, don Marcos kashan. Payqa mana kusisqachu — sayk'usqa kashan.", "e": "Allí está don Marcos. Él no está feliz — está cansado."}, {"type": "text", "speaker": "inti", "q": "Inti: — Allin p'unchay, don! ¿Imaynalla kashanki?", "e": "Inti: — ¡Buenos días, don! ¿Cómo está?"}, {"type": "text", "speaker": "marcos", "q": "Marcos: — Sayk'usqa kashani... ¿Pitaj qan kanki, wayna?", "e": "Marcos: — Estoy cansado... ¿Quién sos, joven?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Noqa Inti sutikuni. ¿Qanrí, don?", "e": "Inti: — Yo me llamo Inti. ¿Y usted, don?"}, {"type": "text", "speaker": "marcos", "q": "Marcos: — Sutiy Marcos. Kusikuni rejsisuspa. ¿Imapí llajtaman jamunki?", "e": "Marcos: — Mi nombre es Marcos. Encantado. ¿En qué viniste a la ciudad?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Chakipi jamuni. Mana autoyojchu kani.", "e": "Inti: — Vine a pie. No tengo auto."}, {"type": "text", "speaker": "marcos", "q": "Marcos: — ¿Wasichu chayri chajrachu astawan gustasunki?", "e": "Marcos: — ¿Te gusta más la casa o la chacra?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Chajra mayta gustawan! Orqopi chajraqa sumaj.", "e": "Inti: — ¡Me gusta la chacra! La chacra en el cerro es hermosa."}, {"type": "question", "title": "¿Imaynalla kashan don Marcos?", "text": "¿Cómo está don Marcos?", "options": ["Kusisqa (Feliz)", "Sayk'usqa (Cansado)", "Yarqhasqa (Hambriento)"], "correct": 1, "explanation": ""}]}, {"id": "inti-parte-4", "section": 1, "part": 4, "title": "Inti, tapurikoj wayna — Parte 4", "subtitle": "Ana y Carmen", "icon": "👩‍👩‍👧", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Chaymantataj, iskay warmista ñanpi jamunku. Paykunaqa kusisqa kanku.", "e": "Después, dos chicas llegan por el camino. Ellas están felices."}, {"type": "text", "speaker": "inti", "q": "Inti: — Imaynalla! ¿Ima sutiykichej?", "e": "Inti: — ¡Hola! ¿Cómo se llaman ustedes?"}, {"type": "text", "speaker": "narrator", "q": "Warmi 1: — Noqa Ana sutikuni. Payqa Carmen sutikun.", "e": "Chica 1: — Yo me llamo Ana. Ella se llama Carmen."}, {"type": "text", "speaker": "inti", "q": "Inti: — Kusikuni rejsisuspa. ¿Maymanta kankichej?", "e": "Inti: — Encantado de conocerlas. ¿De dónde son ustedes?"}, {"type": "text", "speaker": "carmen", "q": "Carmen: — Noqayku mayu llajtamanta kayku. ¿Qanrí?", "e": "Carmen: — Nosotras somos del pueblo del río. ¿Y vos?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Noqa orqo llajtamanta kani. ¿Imapí qankuna jamunkichej?", "e": "Inti: — Yo soy del pueblo del cerro. ¿En qué vinieron?"}, {"type": "text", "speaker": "ana", "q": "Ana: — Noqayku colectivopi jamuyku. ¿Qanrí, Inti?", "e": "Ana: — Nosotras vinimos en colectivo. ¿Y vos, Inti?"}, {"type": "text", "speaker": "inti", "q": "Inti: — Noqa chakipi jamuni. ¿Mayman qankuna rishankichej?", "e": "Inti: — Yo vine a pie. ¿Adónde están yendo ustedes?"}, {"type": "text", "speaker": "ana", "q": "Ana: — Noqayku qhechua cursoman rishayku. Qanrí, ¿jamunkichu?", "e": "Ana: — Nosotras vamos al curso de quechua. Y vos, ¿venís?"}, {"type": "text", "speaker": "inti", "q": "Inti: — ¡Noqapis! Quechuata yachakuyta munani. Sapa p'unchay risaj.", "e": "Inti: — ¡Yo también! Quiero aprender quechua. Iré todos los días."}, {"type": "question", "title": "¿Imapí jamunku Ana Carmenwan?", "text": "¿En qué vinieron Ana y Carmen?", "options": ["Trenpi (En tren)", "Chakipi (A pie)", "Colectivopi (En colectivo)"], "correct": 2, "explanation": ""}]}, {"id": "inti-parte-5", "section": 1, "part": 5, "title": "Inti, tapurikoj wayna — Parte 5", "subtitle": "El final feliz", "icon": "🌟", "level": "Intermedio", "xp": 20, "badge_id": "inti-parte-5-badge", "scenes": [{"type": "text", "speaker": "narrator", "q": "Kinsa runas sapa p'unchay quechuata yachakunku. Kusisqa kanku.", "e": "Los tres aprenden quechua todos los días. Están felices."}, {"type": "text", "speaker": "narrator", "q": "Inti mana llakisqachu. Mana sayk'usqachu. Kusisqa kashan.", "e": "Inti no está triste. No está cansado. Está feliz."}, {"type": "text", "speaker": "narrator", "q": "Chayqa sumaj p'unchay karqa. Waj runasta rejserqa.", "e": "Fue un día hermoso. Conoció a otras personas."}, {"type": "text", "speaker": "narrator", "q": "Paykunaqa sapa p'unchay parlanku. Quechuata parlanku.", "e": "Ellos hablan todos los días. Hablan quechua."}, {"type": "text", "speaker": "narrator", "q": "Inti wasiyman kutimun. ¡Sayk'usqa, pero kusisqa!", "e": "Inti vuelve a su casa. ¿Cansado, pero feliz!"}, {"type": "question", "title": "¿Imaynalla kashan Inti tukukuypi?", "text": "¿Cómo está Inti al final del cuento?", "options": ["Llakisqa (Triste)", "Sayk'usqa (Cansado)", "Phiñasqa (Enojado)"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-1", "section": 2, "part": 1, "title": "El yachakoj wayna — Parte 1", "subtitle": "El primer día", "icon": "📚", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Jorgitoqa uj wayna. Payqa qhechuata yachakuyta munasqa.", "e": "Jorgito es un joven. Él quería aprender quechua."}, {"type": "text", "speaker": "narrator", "q": "Uj p'unchay, cursoman risaj nispa wasiymanta llojsin.", "e": "Un día, diciendo 'voy a ir al curso', sale de su casa."}, {"type": "text", "speaker": "narrator", "q": "Payqa kusisqa, ichapis manchachisqa ima.", "e": "Él está feliz, pero también un poco asustado."}, {"type": "text", "speaker": "narrator", "q": "Cursopi chayamun. Jatun wasi. Ashkha yachakojkuna kashanku.", "e": "Llega al curso. Una casa grande. Hay muchos alumnos."}, {"type": "text", "speaker": "narrator", "q": "Uj warmi qayllaykun: — ¡Imaynalla! Noqa Marta sutikuni.", "e": "Una chica se acerca: — ¡Hola! Yo me llamo Marta."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Imaynalla! Noqa Jorgito sutikuni. Kusikuni rejsisuspa.", "e": "Jorgito: — ¡Hola! Yo me llamo Jorgito. Encantado de conocerte."}, {"type": "text", "speaker": "marta", "q": "Marta: — ¿Qanpis quechuata yachakuyta munankichu, Jorgito?", "e": "Marta: — ¿Vos también querés aprender quechua, Jorgito?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Arí! Sinchita yachakuyta munani.", "e": "Jorgito: — ¡Sí! Quiero aprender mucho."}, {"type": "question", "title": "¿Imayná kashan Jorgito cursoman chayaspa?", "text": "¿Cómo está Jorgito al llegar al curso?", "options": ["Kusisqa ichapis manchachisqa (Feliz y un poco asustado)", "Llakisqa (Triste)", "Sayk'usqa (Cansado)"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-2", "section": 2, "part": 2, "title": "El yachakoj wayna — Parte 2", "subtitle": "El profesor", "icon": "👨‍🏫", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Yachachejqa yaykumun. Payqa don Roberto.", "e": "El profesor entra. Él es don Roberto."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Allillanchu, yachakojkuna! ¿Imaynalla kankichej?", "e": "Don Roberto: — ¡Hola, alumnos! ¿Cómo están?"}, {"type": "text", "speaker": "yachakojkuna", "q": "Yachakojkuna: — ¡Walejlla, yachachej!", "e": "Alumnos: — ¡Bien nomás, profesor!"}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — Quechuaqa sumaj. ¿Yachakuyta munankichejchu?", "e": "Don Roberto: — El quechua es hermoso. ¿Quieren aprender?"}, {"type": "text", "speaker": "tukuy", "q": "Tukuy: — ¡Arí, yachachej! ¡Yachakuyta munayku!", "e": "Todos: — ¡Sí, profesor! ¡Queremos aprender!"}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Sumaj! Sichus sapa p'unchay jamunkichej chayqa, usqhallata yachakunkichej.", "e": "Don Roberto: — ¡Muy bien! Si vienen todos los días, aprenderán rápido."}, {"type": "text", "speaker": "narrator", "q": "Jorgito yuyarin: 'Sapa p'unchay jamusaj. Mana pantasajchu.'", "e": "Jorgito piensa: 'Voy a venir todos los días. No me voy a equivocar.'"}, {"type": "question", "title": "¿Imatá nin don Roberto yachakojkunaman?", "text": "¿Qué les dice don Roberto a los alumnos?", "options": ["Sichus sapa p'unchay jamunkichej chayqa, usqhayllata yachakunkichej (Si vienen todos los días aprenderán rápido)", "Mana yachachisajchu (No voy a enseñar)", "Qhechuaqa mana facilchu (El quechua no es fácil)"], "correct": 0, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-3", "section": 2, "part": 3, "title": "El yachakoj wayna — Parte 3", "subtitle": "La primera lección", "icon": "✏️", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Uj kaj lecciónpi, don Roberto tapun: — ¿Ima sutiykichej?", "e": "En la primera lección, don Roberto pregunta: — ¿Cómo se llaman?"}, {"type": "text", "speaker": "marta", "q": "Marta: — Noqa Marta sutikuni. Moreno llajtamanta kani.", "e": "Marta: — Yo me llamo Marta. Soy de la ciudad de Moreno."}, {"type": "text", "speaker": "carlos", "q": "Carlos: — Noqa Carlos. Noqapis Moreno llajtamanta kani.", "e": "Carlos: — Yo soy Carlos. Yo también soy de la ciudad de Moreno."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Noqa Jorgito sutikuni. Pilar llajtamanta kani.", "e": "Jorgito: — Yo me llamo Jorgito. Soy de la ciudad de Pilar."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Sumaj! ¿Imapí cursoman jamunkichej?", "e": "Don Roberto: — ¡Muy bien! ¿En qué vienen al curso?"}, {"type": "text", "speaker": "marta", "q": "Marta: — Noqa colectivopi jamuni.", "e": "Marta: — Yo vengo en colectivo."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Noqa chakipi jamuni. Wasiy karu kashan.", "e": "Jorgito: — Yo vengo a pie. Mi casa está lejos."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Kallpachakuy, Jorgito! Allinta ruwanki.", "e": "Don Roberto: — ¡Esforzate, Jorgito! Lo hacés muy bien."}, {"type": "question", "title": "¿Maymantataj Jorgito?", "text": "¿De dónde es Jorgito?", "options": ["Orqo llajtamanta", "Pilar llajtamanta", "Moreno llajtamanta"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-4", "section": 2, "part": 4, "title": "El yachakoj wayna — Parte 4", "subtitle": "La dificultad", "icon": "😰", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Kinsa p'unchay pasajtin, Jorgitoqa sayk'usqa kasqa.", "e": "Cuando pasaron tres días. Jorgito estaba cansado."}, {"type": "text", "speaker": "narrator", "q": "Payqa llakisqa kaspa, nerqa: 'Quechuaqa mana facilchu. Mana entiendenichu.'nispa", "e": "Él estando triste dijo: 'El quechua no es fácil. No entiendo.'"}, {"type": "text", "speaker": "narrator", "q": "Cursopi, Jorgito pantarqa. Chaymantataj yachachejqa payta taporqa.", "e": "En el curso, Jorgito se equivocó. Después de eso, el profesor le preguntó."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — Jorgito, ¿imayná kakushanki?", "e": "Don Roberto: — Jorgito, ¿cómo te encuentras?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Llakisqa kashani, yachachejníy. Mana parlayta atinichu.", "e": "Jorgito: — Estoy triste, profesor. No puedo hablar."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Ama llakikuychu! Tukuy pantanchej qallarispa.", "e": "Don Roberto: — ¡No te pongas triste! Todos nos equivocamos al empezar."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — Qan kallpachakushanki. Yachakuyta atinki.", "e": "Don Roberto: — Vos te estás esforzando. Podrás aprender."}, {"type": "text", "speaker": "narrator", "q": "Jorgito uyarin. Pisimanta pisi kusikun.", "e": "Jorgito escucha. De a poco se alegra."}, {"type": "question", "title": "¿Imaraykuchus llakisqa kashan Jorgito?", "text": "¿Por qué está triste Jorgito?", "options": ["Wasiman kutimusqanrayku", "Sayk'usqa kasqanrayku", "Mana parlayta atisqanrayku"], "correct": 2, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-5", "section": 2, "part": 5, "title": "El yachakoj wayna — Parte 5", "subtitle": "Los compañeros", "icon": "👫", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Chaymanta, Marta Carlostawan Jorgitoman qayllaykunku.", "e": "Después, Marta y Carlos se acercan a Jorgito."}, {"type": "text", "speaker": "marta", "q": "Marta: — ¡Ama llakikuychu, Jorgito! Noqaykupis pantarqayku qallarispa.", "e": "Marta: — ¡No te pongas triste, Jorgito! Nosotros también nos equivocamos al empezar."}, {"type": "text", "speaker": "carlos", "q": "Carlos: — Noqa kinsa watasta yachakushani. Kunanqa parlayta atikuni.", "e": "Carlos: — Yo llevo tres años aprendiendo. Ahora puedo hablar."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — ¿Kinsa watasta? ¡Unay tiempo!", "e": "Jorgito: — ¿Tres años? ¡Mucho tiempo!"}, {"type": "text", "speaker": "marta", "q": "Marta: — Mana. Usqhayllata pasarqa. Sapa p'unchay yachakuspa, usqhayllata yachakunki.", "e": "Marta: — No. Pasó rápido. Aprendiendo todos los días, aprenderás rápido."}, {"type": "text", "speaker": "carlos", "q": "Carlos: — ¿Mashkha watasniyoj kanki, Jorgito?", "e": "Carlos: — ¿Cuántos años tenés, Jorgito?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Noqa iskay chunka kinsayoj watasniyoj kani.", "e": "Jorgito: — Yo tengo 23 años."}, {"type": "text", "speaker": "marta", "q": "Marta: — ¡Wayna kanki! Ashka tiempoyoj kanki yachakunaykipaj.", "e": "Marta: — ¡Sos joven! Tenés mucho tiempo para aprender."}, {"type": "text", "speaker": "narrator", "q": "Jorgito sonqonpi kusikun.", "e": "Jorgito se alegra en su corazón."}, {"type": "question", "title": "¿Mashkha watasniyoj kashan Carlos qhechuata yachakuspa?", "text": "¿Cuánto tiempo lleva Carlos aprendiendo quechua?", "options": ["Uj wata", "Iskay watas", "Kinsa watas"], "correct": 2, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-6", "section": 2, "part": 6, "title": "El yachakoj wayna — Parte 6", "subtitle": "El esfuerzo", "icon": "💪", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Chaymanta, Jorgito sapa p'unchay cursoman rerqa.", "e": "Después de eso, Jorgito fue al curso todos los días."}, {"type": "text", "speaker": "narrator", "q": "Sichus paramushan chayqa, chakipi rerqa. Sichus chirimushan chayqa, chakipi rerqa.", "e": "Cuando estaba lloviendo, fue a pie. Cuando estaba frío, fue a pie."}, {"type": "text", "speaker": "narrator", "q": "Payqa yuyaj: 'Ama saqenichu. Sapa p'unchay risaj.'", "e": "Él pensaba: 'No voy a abandonar. Iré todos los días.'"}, {"type": "text", "speaker": "narrator", "q": "Uj p'unchay, don Roberto taporqa: — ¿Imapí cursoman jamunki, Jorgito?", "e": "Un día, don Roberto preguntó: — ¿En qué venís al curso, Jorgito?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Chakipi jamuni, yachachejníy. Wasiy karu kashan.", "e": "Jorgito: — Vengo a pie, profesor. Mi casa está lejos."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¿Autopichu colectivopíchu jamuyta atinki?", "e": "Don Roberto: — ¿Podés venir en auto o en colectivo?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Mana qolqe kanchu. Chakillapi tukuy ladoman rini.", "e": "Jorgito: — No hay dinero. Voy solo a pie a todos lados."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto sonqonpi llakikun. Payqa Jorgitota mayta valoran.", "e": "Don Roberto se entristece en su corazón. Él valora a Jorgito."}, {"type": "question", "title": "¿Imaraykutaj chakipi rin Jorgito?", "text": "¿Por qué Jorgito va a pie?", "options": ["Karu kashan", "Mana qolqe kanchu", "Puriyta munan"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-7", "section": 2, "part": 7, "title": "El yachakoj wayna — Parte 7", "subtitle": "El progreso", "icon": "🌱", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Tawa chunka p'unchay pasajtin, Jorgito astawanraj yachakun.", "e": "Cuando pasaron cuarenta días. Jorgito aprende aún más."}, {"type": "text", "speaker": "narrator", "q": "Kunanqa wakin palabrasta parlayta atin.", "e": "Ahora puede hablar algunas palabras."}, {"type": "text", "speaker": "narrator", "q": "Uj p'unchay, Marta taporqa: — ¿Imaynalla kashanki, Jorgito?", "e": "Un día, Marta preguntó: — ¿Cómo estás, Jorgito?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — ¡Kusisqa kashani! Kunan wakin palabrasta parlayta atini.", "e": "Jorgito: — ¡Estoy feliz! Ahora puedo hablar algunas palabras."}, {"type": "text", "speaker": "marta", "q": "Marta: — ¡Sumaj! ¿Astawan yachakunkichu?", "e": "Marta: — ¡Qué bueno! ¿Aprendiste más?"}, {"type": "text", "speaker": "narrator", "q": "Jorgito quechuapi kutichin: — Arí, gracias! Sapa día astawan yachakuni", "e": "Jorgito responde en quechua: — Arí, gracias! Cada día aprendo más"}, {"type": "text", "speaker": "marta", "q": "Marta: — ¡Sapa kuti aswan allinta parlanki!", "e": "Marta: — ¡Hablás mejor cada vez!"}, {"type": "text", "speaker": "narrator", "q": "Jorgito sonqonpi kusikun.", "e": "Jorgito se alegra en su corazón."}, {"type": "question", "title": "¿Imayná kashan Jorgito tiempo pasajtin?", "text": "¿Cómo está Jorgito al pasar el tiempo?", "options": ["Llakisqa", "Kusisqa", "Sayk'usqa"], "correct": 1, "explanation": ""}, {"type": "question", "title": "¿Maskha tiempotaj pasarqa Jorgito astawanraj yachakunanpaj?", "text": "¿Cuánto tiempo pasó para que jorgito aprendiera aún más?", "options": ["Tawa chunka días", "iskay chunka días", "Kinsa chunka días"], "correct": 0, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-8", "section": 2, "part": 8, "title": "El yachakoj wayna — Parte 8", "subtitle": "La lluvia y la promesa", "icon": "🌧️", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Uj p'unchay, sinch'ita paramushan, wayramushan ima.", "e": "Un día, llueve mucho, y hace viento."}, {"type": "text", "speaker": "narrator", "q": "Wakin yachakojkuna mana jamushankuchu. Paykunaqa wasinkupi kashanku.", "e": "Algunos alumnos no vienen. Ellos están en sus casas."}, {"type": "text", "speaker": "narrator", "q": "Pero Jorgito, paychá chayamonqa. Joq'ochasqa kajtinpis, pay jamonqa.", "e": "Pero Jorgito, el seguro llegará. Aunque nieve, el vendrá."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — ¡Jorgito! ¿Chakipi jamunkichu kay sinch'i parawan?", "e": "Don Roberto: — ¡Jorgito! ¿Has venido a pie con esta gran lluvia?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Arí, yachachejníy. Mana saqesajchu nispa jamorqani.", "e": "Jorgito: — Sí, profesor. Vine diciendo que no voy a abandonar."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto mayta kusikun.", "e": "Don Roberto se alegra mucho."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto: — Qan, Jorgito, sumaj yachakoj kanki. Yachachejniyki kusikun.", "e": "Don Roberto: — Vos, Jorgito, sos un gran alumno. Tu profesor se alegra."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — ¡Noqapis kusikuni, yachachejníy! Parlayta yachachiwanki.", "e": "Jorgito: — ¡Yo también estoy feliz, profesor! Me enseñás a hablar."}, {"type": "question", "title": "¿Imarayku jamorqa Jorgito parawan?", "text": "¿Por qué vino Jorgito bajo la lluvia?", "options": ["Colectivopi jamusqanrayku", "Mana saqeyta munasqanrayku", "Paramushasqanrayku"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-9", "section": 2, "part": 9, "title": "El yachakoj wayna — Parte 9", "subtitle": "La conversación", "icon": "💬", "level": "Intermedio", "xp": 20, "badge_id": null, "scenes": [{"type": "text", "speaker": "narrator", "q": "Sojta killapi, Jorgito ashkhata yachakorqa.", "e": "En seis meses, Jorgito aprendió mucho."}, {"type": "text", "speaker": "narrator", "q": "Uj p'unchay, Carlos payta taporqa qhechuapi:", "e": "Un día, Carlos le preguntó en quechua:"}, {"type": "text", "speaker": "carlos", "q": "Carlos: — ¿Imaynalla kashanki, Jorgito? ¿Quechuata parlayta atinkichu?", "e": "Carlos: — ¿Cómo estás, Jorgito? ¿Podés hablar quechua?"}, {"type": "text", "speaker": "narrator", "q": "Jorgito qhechuapi kutichin: — Walejlla kashani. Kunanqa parlayta atikuni.", "e": "Jorgito responde en quechua: — Estoy bien. Ahora puedo hablar."}, {"type": "text", "speaker": "carlos", "q": "Carlos: — ¡Sumaj! ¿Maymanta jamunki?", "e": "Carlos: — ¡Qué hermoso! ¿De dónde vienes?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Orqo llajtamanta kani. Chakipi cursoman jamuni.", "e": "Jorgito: — Soy del pueblo del cerro. Vengo a pie al curso."}, {"type": "text", "speaker": "carlos", "q": "Carlos: — ¿Mashkha watasniyoj kanki?", "e": "Carlos: — ¿Cuántos años tenés?"}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Iskay chunka kinsayoj watasniyoj kani. ¿Qanrí?", "e": "Jorgito: — Tengo 23 años. ¿Y vos?"}, {"type": "text", "speaker": "carlos", "q": "Carlos: — Noqa iskay chunka pichqayoj watasniyoj kani.", "e": "Carlos: — Yo tengo 25 años."}, {"type": "question", "title": "¿Mashkha tiempotaj parlayta yachakorqa Jorgito?", "text": "¿En cuántos meses aprendió Jorgito a hablar?", "options": ["Kinsa killapi (En tres meses)", "Sojta killapi (En seis meses)", "Uj killapi (En un mes)"], "correct": 1, "explanation": ""}]}, {"id": "yachakoj-wayna-parte-10", "section": 2, "part": 10, "title": "El yachakoj wayna — Parte 10", "subtitle": "El futuro", "icon": "⭐", "level": "Intermedio", "xp": 20, "badge_id": "yachakoj-wayna-parte-10-badge", "scenes": [{"type": "text", "speaker": "narrator", "q": "Tukuynin leccionesta junt'akorqa.", "e": "Todas las lecciones se completaron."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto yachakojkunaman nin:", "e": "Don Roberto les dice a los alumnos:"}, {"type": "text", "speaker": "narrator", "q": "— ¡Sumajta ruwankichej! Sapa p'unchay yachakusqaykichejrayku, ashkata yachankichej.", "e": "— ¡Lo hicieron muy bien! Por haber aprendido todos los días, saben mucho."}, {"type": "text", "speaker": "narrator", "q": "Don Roberto Jorgitoman qhawan: — Qanqa, Jorgito, astawan kallpachakunki yachakunaykipaj.", "e": "Don Roberto mira a Jorgito: — Vos, Jorgito, te esforzaste más por aprender."}, {"type": "text", "speaker": "jorgito", "q": "Jorgito: — Yachachejníy, qan sapa día yachachiwanki. Noqa yachakusaj.", "e": "Jorgito: — Profesor, vos cada dia me enseñas. Yo aprenderé."}, {"type": "text", "speaker": "marta", "q": "Marta: — ¡Q'aya noqanchej tukuyta qhechuata parlarisunchej!", "e": "Marta: — ¡Mañana nosotros a todos hablaremos quechua!"}, {"type": "text", "speaker": "carlos", "q": "Carlos: — ¡Arí! ¡Ichá kinsa watapi Jorgito aswan allinta parlanqa!", "e": "Carlos: — ¡Sí! ¡Tal vez en tres años Jorgito hablará aún mejor!"}, {"type": "text", "speaker": "narrator", "q": "Jorgito sonqonpi kusikun. Ñawisninpi kusiy tiyan.", "e": "Jorgito se alegra en su corazón. En sus ojos hay alegría."}, {"type": "text", "speaker": "narrator", "q": "Payqa yuyarin: 'Mana saqenichu. Sapa p'unchay yachakusaj. Uj p'unchay quechuata parlayta atisaj.'", "e": "Él piensa: 'No voy a abandonar. Aprenderé todos los días. Algún día podré hablar quechua.'"}, {"type": "text", "speaker": "narrator", "q": "Chayqa sumaj meta — ¡Ama saqeychu!", "e": "Esa es una excelente meta — ¡no abandones!"}, {"type": "question", "title": "¿Imatá yuyarin Jorgito tukukuypi?", "text": "¿Qué piensa Jorgito al final?", "options": ["Yachaniña, manaña yachakusajchu (Ya sé, no voy a aprender)", "Mana saqesajchu, sapa p'unchay yachakusaj (No voy a abandonar, aprenderé todos los días)", "Wasiman kutisaj, manaña cursoman risajchu (Voy a volver a casa, ya no iré al curso)"], "correct": 1, "explanation": ""}]}];